function uniqueXorTriplets(nums: number[]): number {
    const n = nums.length;
    if (n <= 2) {
        return n;
    }
    return 1 << (32 - Math.clz32(n));
}

impl Solution {
    pub fn unique_xor_triplets(nums: Vec<i32>) -> i32 {
        let length = nums.len() as i32;
        if length < 3 {
            return length;
        }
        1 << (length.ilog2() + 1)
    }
}
